2	 * Claims due call runs. PostgreSQL owns the claim so concurrent cron requests
3	 * cannot send the same run to CALL-E twice.
4	 *
5	 * T2.4 wires each claimed run to the guarded CALL-E dispatcher.
6	 *
7	 * Pin with: deno test --allow-env --allow-net supabase/functions/tick/index.ts
8	 */
9	
10	import { withSupabase } from "npm:@supabase/server@1.6.0";
11	import {
12	  type CalleDeps,
13	  depsFromEnv as calleDepsFromEnv,
14	  dispatchClaimedRun,
15	} from "../_shared/calle.ts";
16	import { recordCallEvent } from "../_shared/events.ts";
17	import { pollRun } from "../_shared/poll.ts";
