51	export function requireNamedEnv(
52	  name: string,
53	  getEnv: (key: string) => string | undefined = (key) => Deno.env.get(key),
54	): string {
55	  const value = getEnv(name);
56	  if (!value) throw new Error(`missing ${name}`);
57	  return value;
58	}
59	
60	function unavailable(stage: string): (run: TickRun) => Promise<void> {
61	  return async () => {
62	    throw new Error(`${stage} implementation is unavailable`);
63	  };
64	}
