66	/**
67	 * One run's poll pass, isolated from the rest. A write that fails leaves the
68	 * run's `poll_after` untouched, so the next tick retries it. One broken run
69	 * must never cost every other run in the same tick.
70	 */
71	export async function pollStep(
72	  run: TickRun,
73	  calleDeps: CalleDeps,
74	): Promise<void> {
75	  try {
76	    await pollRun(run, calleDeps);
77	  } catch (error) {
78	    console.error(
79	      `poll failed for run ${run.id}`,
80	      error instanceof Error ? error.message : "unknown error",
81	    );
82	  }
83	}
