85	export function depsFromEnv(
86	  getEnv: (key: string) => string | undefined = (key) => Deno.env.get(key),
87	  fetchImpl: typeof fetch = fetch,
88	): TickDeps {
89	  const calleDeps = calleDepsFromEnv(getEnv, fetchImpl);
90	  return {
91	    apiUrl: requireNamedEnv("ORMA_API_URL", getEnv),
92	    serviceRoleKey: requireNamedEnv("SUPABASE_SERVICE_ROLE_KEY", getEnv),
93	    fetch: fetchImpl,
94	    dispatchClaimed: (run) => dispatchClaimedRun(run, calleDeps),
95	    pollDue: (run) => pollStep(run, calleDeps),
96	    finalise: unavailable("finalisation"),
97	    now: () => new Date(),
98	  };
99	}
