115	async function readRows(
116	  deps: TickDeps,
117	  query: URLSearchParams,
118	): Promise<TickRun[]> {
119	  const response = await deps.fetch(
120	    restUrl(deps.apiUrl, "call_runs", query.toString()),
121	    {
122	      headers: serviceHeaders(deps.serviceRoleKey),
123	    },
124	  );
125	  if (!response.ok) throw new Error("call_runs read failed");
126	  return await response.json() as TickRun[];
127	}
