129	/** Calls the only SQL boundary allowed to claim runs. Do not replace this with
130	 * a REST PATCH: PostgREST cannot provide a `FOR UPDATE SKIP LOCKED` claim.
131	 */
132	export async function claimDueRuns(deps: TickDeps): Promise<ClaimedTickRun[]> {
133	  const response = await deps.fetch(
134	    restUrl(deps.apiUrl, "rpc/claim_due_call_runs"),
135	    {
136	      method: "POST",
137	      headers: serviceHeaders(deps.serviceRoleKey),
138	      body: JSON.stringify({ p_limit: CLAIM_LIMIT }),
139	    },
140	  );
141	  if (!response.ok) throw new Error("due call_runs claim failed");
142	  return await response.json() as ClaimedTickRun[];
143	}
