145	export async function duePolls(deps: TickDeps): Promise<TickRun[]> {
146	  const query = new URLSearchParams({
147	    select: "id,state,poll_after",
148	    state: "in.(dispatched,awaiting_result)",
149	    poll_after: `lte.${deps.now().toISOString()}`,
150	    order: "poll_after",
151	    limit: String(CLAIM_LIMIT),
152	  });
153	  return readRows(deps, query);
154	}
155	
156	export async function terminalRuns(deps: TickDeps): Promise<TickRun[]> {
157	  const query = new URLSearchParams({
158	    select: "id,state,poll_after",
159	    state: "in.(completed,no_result,failed,canceled)",
160	    completed_at: "is.null",
161	    order: "scheduled_for",
162	    limit: String(CLAIM_LIMIT),
163	  });
164	  return readRows(deps, query);
165	}
