167	export async function tick(deps: TickDeps): Promise<TickResult> {
168	  const claimed = deps.dispatchClaimed ? await claimDueRuns(deps) : [];
169	  if (deps.dispatchClaimed) {
170	    await Promise.all(claimed.map(async (run) => {
171	      await recordCallEvent(run.id, "claimed", { state: run.state }, deps);
172	      await deps.dispatchClaimed!(run);
173	    }));
174	  }
175	
176	  const polls = await duePolls(deps);
177	  await Promise.all(polls.map((run) => deps.pollDue(run)));
178	
179	  const terminal = await terminalRuns(deps);
180	  // Each run finalises in isolation, like pollStep. One run that cannot
181	  // finalise stays selected for the next tick and costs its siblings nothing.
182	  await Promise.all(terminal.map(async (run) => {
183	    try {
184	      await deps.finalise(run);
185	    } catch (error) {
186	      console.error(
187	        `finalise failed for run ${run.id}`,
188	        error instanceof Error ? error.message : "unknown error",
189	      );
190	    }
191	  }));
192	
193	  return {
194	    claimed: claimed.length,
195	    polled: polls.length,
196	    finalised: terminal.length,
197	  };
198	}
