200	export function createTickHandler(
201	  deps: TickDeps,
202	): (request: Request) => Promise<Response> {
203	  return async (request) => {
204	    if (request.method !== "POST") {
205	      return new Response(null, { status: 405, headers: { allow: "POST" } });
206	    }
207	    try {
208	      return Response.json(await tick(deps));
209	    } catch (error) {
210	      console.error(
211	        "tick failed",
212	        error instanceof Error ? error.message : "unknown error",
213	      );
214	      return new Response(null, { status: 500 });
215	    }
216	  };
217	}
