170	    method: "PATCH",
171	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
172	    body: JSON.stringify({ type: REFRESHING, received_at: new Date(now).toISOString() }),
173	  });
174	  if (!response.ok) throw new Error("webhook event claim failed");
175	  const rows: unknown = await response.json();
