198	/**
199	 * Moves the run to the state the re-fetch reports, and only while the run is
200	 * still pending. The webhook and the poll both write here, so the conditional
201	 * PATCH is what makes exactly one of them win. The body never supplies a
202	 * state, only the authoritative GET does.
203	 */
204	type RefetchOutcome = "applied" | "already_resolved" | "not_terminal";
