206	async function terminaliseFromRefetch(deps: WebhookDeps, call: AuthoritativeCall): Promise<RefetchOutcome> {
207	  const state = terminalStateFor(call.status as CallStatus);
208	  if (!state) return "not_terminal";
209	  const query = new URLSearchParams({
210	    id: `eq.${call.metadata.call_run_id}`,
211	    state: "in.(dispatched,awaiting_result)",
212	  });
213	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
214	    method: "PATCH",
215	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
216	    body: JSON.stringify({ state, poll_after: null }),
217	  });
218	  if (!response.ok) throw new Error("call run terminalisation failed");
219	  const rows = await response.json() as unknown[];
220	  // Zero matched rows means the poll already moved the run. The re-fetched
221	  // status is then a superseded observation, and the timeline must say so.
222	  return Array.isArray(rows) && rows.length === 1 ? "applied" : "already_resolved";
223	}
