240	export function createWebhookHandler(deps: WebhookDeps): (request: Request) => Promise<Response> {
241	  return async (request) => {
242	    if (request.method !== "POST") {
243	      return new Response(null, { status: 405, headers: { allow: "POST" } });
244	    }
245	    const presented = presentedWebhookSecret(new URL(request.url).pathname);
246	    if (!presented || !webhookSecretsMatch(presented, deps.webhookSecret)) {
247	      return new Response(null, { status: 401 });
248	    }
249	    const headerEventId = request.headers.get(EVENT_ID_HEADER);
250	    if (!headerEventId) return new Response(null, { status: 400 });
251	    try {
252	      const body = await request.text();
253	      if (new TextEncoder().encode(body).byteLength > MAX_BODY_BYTES) {
254	        return new Response(null, { status: 413 });
255	      }
256	      const envelope = parseWebhookEnvelope(body, headerEventId);
257	      if (!envelope) return new Response(null, { status: 400 });
258	      await insertPendingEvent(deps, envelope.id);
259	      if (!await claimPendingEvent(deps, envelope.id)) return new Response(null, { status: 200 });
260	      try {
261	        const call = await fetchAuthoritativeCall(deps, envelope.data.id);
262	        if (!call || !await hasMatchingOrmaRun(deps, call)) {
263	          await setEventState(deps, envelope.id, IGNORED);
264	          return new Response(null, { status: 200 });
265	        }
266	        // Persist the transition before the timeline claims it, so a failed
267	        // write never leaves an entry asserting a state that never landed.
268	        // The event row is released to pending below, so this is retried.
269	        const outcome = await terminaliseFromRefetch(deps, call);
270	        const eventDeps = { apiUrl: deps.apiUrl, serviceRoleKey: deps.serviceRoleKey, fetch: deps.fetch };
271	        await recordCallEvent(
272	          call.metadata.call_run_id,
273	          "webhook_received",
274	          { calle_call_id: call.id, event_type: envelope.type },
275	          eventDeps,
276	        );
277	        await recordCallEvent(
278	          call.metadata.call_run_id,
279	          "refetched",
280	          { calle_call_id: call.id, event_type: envelope.type, state: call.status, outcome },
281	          eventDeps,
282	        );
283	        await setEventState(deps, envelope.id, REFETCHED);
284	        return new Response(null, { status: 200 });
285	      } catch (error) {
286	        try {
287	          await setEventState(deps, envelope.id, PENDING);
288	        } catch (releaseError) {
289	          console.error("calle webhook event release failed", releaseError instanceof Error ? releaseError.message : "unknown error");
290	        }
291	        throw error;
292	      }
293	    } catch (error) {
294	      console.error("calle webhook re-fetch failed", error instanceof Error ? error.message : "unknown error");
295	      return new Response(null, { status: 500 });
296	    }
297	  };
298	}
