const runByCall = new Map<string, string>();
const refetches = new Map<string, number>();
const stub: typeof fetch = async (input, init) => {
  const request = new Request(input, init);
  const url = new URL(request.url);
  if (url.host === "api.call-e.test") {
    if (request.method !== "GET") return new Response(null, { status: 599 });
    const id = url.pathname.split("/").pop()!;
    const fake = fakes.get(id);
    if (!fake) return new Response(null, { status: 404 });
    if (fake.delayMs) await sleep(fake.delayMs);
    refetches.set(id, (refetches.get(id) ?? 0) + 1);
    if (fake.httpStatus) return new Response(null, { status: fake.httpStatus });
