  await createRun("T-terminal", { state: "completed", dispatched_at: ago(180_000) }, t);
  await createRun("T-sibling", { state: "awaiting_result", dispatched_at: ago(120_000), poll_after: ago(1_000) }, s);
  fakes.set(s, { status: "completed" });
  await guardForeignRows();
  const response = await createTickHandler(tickDepsFromEnv(env, stub))(new Request(`${API}/functions/v1/tick`, { method: "POST" }));
  console.log(`T-tick-status=${response.status} body=${await response.text()}`);
}

if (mode === "R") {
  // Regression. Both race orderings, three rounds each, exactly one winner.
  for (const order of ["poll-first", "webhook-first"]) {
    for (let round = 1; round <= 3; round++) {
      const c = `call_rem2_r_${order}_${round}_${tag}`;
      const id = await createRun(`R-${order}-${round}`, { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: ago(1_000) }, c);
      fakes.set(c, { status: "completed" });
      const slowPoll: typeof fetch = async (input, init) => {
        const request = new Request(input, init);
        if (order === "webhook-first" && new URL(request.url).host === "api.call-e.test") await sleep(150);
        return await stub(request);
      };
      const hookStub: typeof fetch = async (input, init) => {
        const request = new Request(input, init);
        if (new URL(request.url).host === "api.call-e.test") {
          const body = await (await stub(request)).json();
          body.status = "failed";
          if (order === "poll-first") await sleep(150);
          return Response.json(body);
        }
        return await stub(request);
      };
      const [, status] = await Promise.all([
        pollRun({ id, state: "awaiting_result", poll_after: null }, calleDepsFromEnv(env, slowPoll)),
        deliver(c, `evt_rem2_r_${order}_${round}_${tag}`, hookStub, "call.failed"),
      ]);
      console.log(`R-${order}-${round}-webhook-status=${status}`);
    }
  }
}
